-- Correct builtin predicates only; preserve enabled state, IDs, hit counts and user rules.
UPDATE trace_detection_rules SET name = 'Tag pg_isready shadow access', description = 'Record pg_isready shadow access without assuming a health check legitimizes credential access.', action = 'tag', conditions = '[{"field":"comm","op":"eq","value":"pg_isready"},{"field":"filename","op":"eq","value":"/etc/shadow"}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["postgresql","credential-access"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade pg_isready shadow read';
UPDATE trace_detection_rules SET name = 'Downgrade pg_isready passwd read', description = 'pg_isready reads /etc/passwd during health checks. Expected behavior.', action = 'downgrade', conditions = '[{"field":"comm","op":"eq","value":"pg_isready"},{"field":"filename","op":"eq","value":"/etc/passwd"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, severity_override = 0, tags = ARRAY(SELECT jsonb_array_elements_text('["postgresql","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade pg_isready passwd read';
UPDATE trace_detection_rules SET name = 'Suppress logrotate log access', description = 'logrotate accessing /var/log is its intended purpose.', action = 'suppress', conditions = '[{"field":"comm","op":"eq","value":"logrotate"},{"field":"filename","op":"starts_with","value":"/var/log/"}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["logrotate","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Suppress logrotate log access';
UPDATE trace_detection_rules SET name = 'Suppress local health-check curl', description = 'curl connecting to 127.0.0.1 or localhost is typically a health check probe.', action = 'suppress', conditions = '[{"field":"comm","op":"eq","value":"curl"},{"field":"addr","op":"eq","value":"127.0.0.1"}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["health-check","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Suppress local health-check curl';
UPDATE trace_detection_rules SET name = 'Tag unknown binary root UID request', description = 'Record root UID requests without overriding kernel classification: payload UID is real UID and does not establish the effective UID.', action = 'tag', conditions = '[{"field":"uid","op":"gte","value":1},{"field":"detail","op":"eq","value":0},{"field":"event_name","op":"eq","value":"setuid"},{"field":"comm","op":"not_in","value":["sshd","sshd-session","sshd-auth","su","sudo","login","passwd","newgrp","runuser","su-l","runc","runc:[2:INIT]","containerd-shim","containerd","dockerd","kubelet","cron","crond","at","systemd","nginx","mysqld","mariadbd","postgres","redis-server","dovecot","haproxy","varnishd","openvpn","memcached","zabbix_agentd","unattended-upgr","apt.systemd.dai","ansible","osqueryi"]}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["credential-change","review"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Escalate unknown binary setuid';
UPDATE trace_detection_rules SET name = 'Escalate /etc/shadow read by unknown process', description = 'Reading /etc/shadow outside of known auth processes is a strong indicator of credential harvesting.', action = 'escalate', conditions = '[{"field":"filename","op":"eq","value":"/etc/shadow"},{"field":"comm","op":"not_in","value":["sshd","sshd-session","sshd-auth","login","passwd","chage","useradd","usermod","pg_isready","postgres","shadow","unix_chkpwd","ansible","chef-client","puppet","osqueryi","aide","tripwire","restic","borg","bacula-fd","urbackupclient","backuppc"]}]'::jsonb, severity_override = 4, tags = ARRAY(SELECT jsonb_array_elements_text('["credential-access","high-signal"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Escalate /etc/shadow read by unknown process';
UPDATE trace_detection_rules SET name = 'Tag crontab modification', description = 'Writing to /var/spool/cron may indicate persistence via cron backdoor.', action = 'tag', conditions = '[{"field":"filename","op":"starts_with","value":"/var/spool/cron/"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_and","value":3}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["persistence","cron"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Tag crontab modification';
UPDATE trace_detection_rules SET name = 'Downgrade auth daemon PAM config reads', description = 'sshd, login, su, sudo and other auth daemons routinely read /etc/pam.d/* as part of the normal authentication flow. Not an attack.', action = 'downgrade', conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["sshd","login","su","sudo","unix_chkpwd","passwd","systemd-logind","gdm","gdm3","lightdm","polkitd","dbus-daemon","pam_unix","nologin"]},{"field":"filename","op":"starts_with","value":"/etc/pam.d/"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, severity_override = 0, tags = ARRAY(SELECT jsonb_array_elements_text('["auth","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade auth daemon PAM config reads';
UPDATE trace_detection_rules SET name = 'Downgrade auth daemon security config reads', description = 'Auth daemons reading /etc/security/* (limits, access, etc.) is part of PAM stack execution — expected behavior.', action = 'downgrade', conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["sshd","login","su","sudo","unix_chkpwd","passwd","systemd-logind","polkitd"]},{"field":"filename","op":"starts_with","value":"/etc/security/"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, severity_override = 0, tags = ARRAY(SELECT jsonb_array_elements_text('["auth","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade auth daemon security config reads';
UPDATE trace_detection_rules SET name = 'Downgrade sshd SSH config reads', description = 'sshd reads /etc/ssh/sshd_config and host key files on startup and during connection. Expected operation.', action = 'downgrade', conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"eq","value":"sshd"},{"field":"filename","op":"starts_with","value":"/etc/ssh/"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, severity_override = 1, tags = ARRAY(SELECT jsonb_array_elements_text('["ssh","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade sshd SSH config reads';
UPDATE trace_detection_rules SET name = 'Downgrade init system /etc reads', description = 'systemd and init read most of /etc/ during boot and service management. These are expected reads.', action = 'downgrade', conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["systemd","init","systemd-udevd"]},{"field":"filename","op":"starts_with","value":"/etc/"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, severity_override = 1, tags = ARRAY(SELECT jsonb_array_elements_text('["init","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade init system /etc reads';
UPDATE trace_detection_rules SET name = 'Downgrade package manager /etc reads', description = 'Package managers (apt, dpkg, yum, dnf) read /etc/ to check installed configs. Expected during updates.', action = 'downgrade', conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["apt","apt-get","dpkg","dpkg-deb","yum","dnf","rpm"]},{"field":"filename","op":"starts_with","value":"/etc/"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, severity_override = 0, tags = ARRAY(SELECT jsonb_array_elements_text('["package-manager","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade package manager /etc reads';
UPDATE trace_detection_rules SET name = 'Downgrade monitoring agent /proc reads', description = 'Monitoring agents (WAFio, node_exporter, prometheus, telegraf) read /proc/* for metrics collection. Expected behavior.', action = 'downgrade', conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["node_exporter","prometheus","telegraf","datadog-agent","collectd","zabbix_agentd"]},{"field":"filename","op":"starts_with","value":"/proc/"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, severity_override = 0, tags = ARRAY(SELECT jsonb_array_elements_text('["monitoring","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade monitoring agent /proc reads';
UPDATE trace_detection_rules SET name = 'Escalate interpreter /etc/shadow read', description = 'A shell or interpreter (bash, python, perl, ruby) reading /etc/shadow indicates potential credential harvesting — web shell or post-exploitation.', action = 'escalate', conditions = '[{"field":"event_name","op":"eq","value":"openat"},{"field":"comm","op":"in","value":["bash","sh","dash","zsh","python","python3","perl","ruby","php","lua"]},{"field":"filename","op":"eq","value":"/etc/shadow"}]'::jsonb, severity_override = 4, tags = ARRAY(SELECT jsonb_array_elements_text('["credential-access","web-shell","high-signal"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Escalate interpreter /etc/shadow read';
